def stage_snapshot(root):
 with h.directory(root,stage) as fd:
  before=r.stamp(os.fstat(fd))
  assert {k:before[k] for k in ('dev','ino','mode','uid','gid','nlink')}=={k:expected_stage[k] for k in ('dev','ino','mode','uid','gid','nlink')}
  assert set(os.listdir(fd))==set(pins)|{'result_root01.json'}
  values={}
  for name,pin in pins.items():
   info=os.stat(name,dir_fd=fd,follow_symlinks=False)
   assert stat.S_ISREG(info.st_mode) and info.st_nlink==1 and info.st_uid==info.st_gid==1000
   raw,unused=h.read_file(fd,name,pin['bytes'])
   assert len(raw)==pin['bytes'] and hashlib.sha256(raw).hexdigest()==pin['sha256']
   assert r.stamp(os.stat(name,dir_fd=fd,follow_symlinks=False))==r.stamp(info)
   values[name]={'identity':r.stamp(info),'sha256':pin['sha256']}
  assert values==expected_sources
  info=os.stat('result_root01.json',dir_fd=fd,follow_symlinks=False)
  assert stat.S_ISREG(info.st_mode) and info.st_nlink==1 and info.st_uid==info.st_gid==1000 and 0<info.st_size<=65536
  raw,descriptor=h.read_file(fd,'result_root01.json',65536)
  assert r.stamp(os.stat('result_root01.json',dir_fd=fd,follow_symlinks=False))==r.stamp(info)
  result={'identity':r.stamp(info),'descriptor_identity':descriptor,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
  assert set(os.listdir(fd))==set(pins)|{'result_root01.json'} and r.stamp(os.fstat(fd))==before
  return {'directory':before,'files':values,'result':result},raw
def scratch_absent(root):
 with h.directory(root,'/tmp') as fd:
  try:os.stat('remoteocd',dir_fd=fd,follow_symlinks=False)
  except FileNotFoundError:return True
  raise ValueError('Scratch path still exists')
def original_snapshot(root):
 values={}
 for name,pin in r.PINS.items():
  parent,basename=pin[2].rsplit('/',1)
  with h.directory(root,parent) as fd:
   before=r.stamp(os.stat(basename,dir_fd=fd,follow_symlinks=False))
   assert stat.S_ISREG(before['mode']) and before['uid']==before['gid']==1000 and before['nlink']==1
   raw,descriptor=h.read_file(fd,basename,pin[0]);r.checked_bytes(raw,pin)
   assert r.stamp(os.stat(basename,dir_fd=fd,follow_symlinks=False))==before
   values[name]={'path':pin[2],'identity':before,'descriptor_identity':descriptor,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()}
 assert values==expected_originals
 return values
